200	// 来源槽的历史补进列表。
201	//
202	// 列表只做完整性检查，不筛选规则版本：History 没有可接受版本参数，一份
203	// 记录只要确实保存生效且通过与 Record 一致的完整性检查——标识与文件一致、
204	// 记录格式受支持、内容校验和正确（含父记录关系）、世界状态合法、直接父
205	// 记录文件存在——即使规则版本较旧或陌生也照常列出。因此“出现在列表里”
206	// 只说明记录完好，不保证调用方立即可用：用 Record 读取时仍必须显式给出
207	// 可接受版本集合，版本不被接受会得到 *VersionRejectedError，不能据此认为
208	// 历史列错了。
209	//
210	// 带历史索引的槽中，单条损坏、缺失或无法解析的记录只被略过，列表继续
211	// 返回其余合格记录，最新或某条中间记录出问题不会让整个浏览失败；但直接
212	// 父记录文件被删除的子记录因不满足父关系要求也被略过，而父文件仍在、
213	// 只是内容损坏时，不因此略过自身完好的子记录。旧版本写出的无历史索引槽
214	// 沿校验通过的父链在内存中重建，只列仍能确认归属本槽的记录，重建在损坏
215	// 处停止，不能承诺越过损坏处继续寻找更老的记录。
216	//
217	// 槽存在但没有任何合格记录时，返回成功的非 nil 空列表；槽不存在返回
218	// *NotFoundError，槽指针无法解析返回 *CorruptError，三者互不等同，不能把
219	// 不存在或损坏当成空列表。浏览只做只读遍历，不切换槽当前记录、不修补或
220	// 删除记录、不改写历史与世界规则。
221	func (a *Archive) History(slot string) ([]RecordInfo, error) {
222		if !validSlotName(slot) {
223			return nil, &NotFoundError{Slot: slot}
224		}
225		lock, err := acquireSharedLock(a.dir)
226		if err != nil {
227			return nil, err
228		}
229		defer lock.release()
230	
231		history, err := a.slotHistoryLocked(slot)
232		if err != nil {
233			return nil, err
234		}
235		infos := make([]RecordInfo, 0, len(history))
236		for _, id := range history {
237			// 与 Record 相同的完整性检查（不做规则版本取舍）：任何一条
238			// 记录损坏、缺失或无法解析都只略过它本身，不读其中的父标识或
239			// 槽首标记去扩大或缩小遍历范围，也不让整个列表失败。
240			env, verifyErr := a.loadAndVerifyLocked(id)
241			if verifyErr != nil {
242				continue
243			}
244			infos = append(infos, RecordInfo{
245				ID:        env.ID,
246				Parent:    env.Parent,
247				SlotFirst: env.SlotFirst,
248				Version:   env.State.Rules.Version,
249			})
250		}
251		return infos, nil
252	}
253	
254	// RecoverLatest 返回该槽“按保存生效次序最近的一份”内容校验通过且规则
255	// 版本可接受的已保存记录。
256	//
257	// 遍历次序完全来自槽指针维护的历史索引（最新在前），既不依据文件修改
258	// 时间，也不读取受损记录里的父标识或槽首标记：因此最新记录被删除、
259	// 截断成无法解析的内容，或连同若干中间记录一起损坏时，仍能越过它们
260	// 找到本槽更早的可用记录，而不会被引向别的槽或遮住更早的可用记录。遍历
261	// 次序与世界时间片的大小无关；时间片为负的记录属于损坏记录，同样被越过。
262	// 格式版本不受支持的记录（即使校验和匹配、状态合法）同样被越过，连续
263	// 多份未知格式记录也不会遮住其后格式受支持的完好记录。
264	//
265	// 分支槽只在分支自身已成功保存的记录中查找；即使分支首条记录损坏也不
266	// 越过分支边界，其他槽即使种子和规则相同也不会替代。版本不被接受的
267	// 记录一律跳过且不自动升级。只有记录文件写完且指针已更新（即保存完整
268	// 生效）的记录才在候选中：残留临时文件、写完但尚未完成保存的孤儿记录
269	// 不会被选中。
270	//
271	// 槽不存在返回 *NotFoundError；槽指针不可读返回 *CorruptError；槽中没有
272	// 任何版本可接受的完好记录时返回包装了 ErrUnrecoverable 的
273	// *UnrecoverableError，可用 errors.Is(err, ErrUnrecoverable) 判断。
274	// 恢复读取不会改写槽、指针、历史记录或规则，重复读取也不消耗历史。
275	func (a *Archive) RecoverLatest(slot string, acceptedVersions []string) (Record, error) {
276		if !validSlotName(slot) {
277			return Record{}, &NotFoundError{Slot: slot}
278		}
279		lock, err := acquireSharedLock(a.dir)
280		if err != nil {
281			return Record{}, err
282		}
283		defer lock.release()
284	
285		history, err := a.slotHistoryLocked(slot)
286		if err != nil {
287			return Record{}, err
288		}
289	
290		env, err := a.firstRecoverableLocked(history, acceptedVersions)
291		if err != nil {
292			var ue *UnrecoverableError
293			if errors.As(err, &ue) {
294				ue.Slot = slot
295			}
296			return Record{}, err
297		}
298		return envToRecord(env), nil
299	}
300	
301	// firstRecoverableLocked 在调用方已持锁的前提下，按给定的保存生效次序
302	// （最新在前）返回第一份“内容与父关系校验通过且规则版本可接受”的记录。
303	//
304	// 文件缺失、截断、格式版本不受支持、校验和不符、记录标识不符、父关系异常、
305	// 时间片为负或世界状态不自洽的记录一律越过（不读其中的父标识或槽首标记）；
306	// 版本不被接受的记录也越过且不自动升级。次序完全由调用方给出（来自槽指针
307	// 历史索引或沿可信父链的重建），因此不会被引向别的槽。没有任何可用记录时
308	// 返回包装了 ErrUnrecoverable 的 *UnrecoverableError（Slot 字段由调用方
309	// 补全）。
310	func (a *Archive) firstRecoverableLocked(history []RecordID, acceptedVersions []string) (*envelope, error) {
311		var lastReason string
312		for _, id := range history {
313			env, verifyErr := a.loadAndVerifyLocked(id)
314			if verifyErr != nil {
315				lastReason = verifyErr.Error()
316				continue
317			}
318			if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
319				lastReason = (&VersionRejectedError{
320					Record:  id,
321					Version: env.State.Rules.Version,
322				}).Error()
323				continue
324			}
325			return env, nil
326		}
327	
328		if lastReason == "" {
329			lastReason = "槽中没有任何可确认归属的历史记录"
330		}
331		return nil, &UnrecoverableError{Reason: lastReason}
332	}
