1	package world
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"strings"
9		"testing"
10	)
11	
12	// rewriteRecordFormat 把已有记录的格式编号改写为给定值并重算内容校验和，
13	// 模拟一份可正常解析、校验和匹配、世界状态合法但格式编号不受支持的记录。
14	func rewriteRecordFormat(t *testing.T, a *Archive, id RecordID, format int) {
15		t.Helper()
16		path := recordPath(a.dir, id)
17		env, err := loadRecord(path)
18		if err != nil {
19			t.Fatal(err)
20		}
21		env.Format = format
22		env.Checksum = computeChecksum(env)
23		data, err := json.MarshalIndent(env, "", "  ")
24		if err != nil {
25			t.Fatal(err)
26		}
27		if err := os.WriteFile(path, data, 0o600); err != nil {
28			t.Fatal(err)
29		}
30	}
31	
32	// dropRecordFormatField 删除记录文件中的 format 字段（其余内容保留），
33	// 并按缺失（即零值）重算校验和，模拟一条没有格式编号的记录。
34	func dropRecordFormatField(t *testing.T, a *Archive, id RecordID) {
35		t.Helper()
36		path := recordPath(a.dir, id)
37		env, err := loadRecord(path)
38		if err != nil {
39			t.Fatal(err)
40		}
41		env.Format = 0
42		env.Checksum = computeChecksum(env)
43		data, err := json.Marshal(env)
44		if err != nil {
45			t.Fatal(err)
46		}
47		var m map[string]any
48		if err := json.Unmarshal(data, &m); err != nil {
49			t.Fatal(err)
50		}
51		delete(m, "format")
52		out, err := json.MarshalIndent(m, "", "  ")
53		if err != nil {
54			t.Fatal(err)
55		}
56		if err := os.WriteFile(path, out, 0o600); err != nil {
57			t.Fatal(err)
58		}
59	}
60	
61	// assertUnsupportedFormatCorrupt 断言 err 是保留了被拒绝记录标识、且说明
62	// 格式编号不受支持的 *CorruptError（而不是版本拒绝或其它错误）。
63	func assertUnsupportedFormatCorrupt(t *testing.T, err error, id RecordID, format int) {
64		t.Helper()
65		ce, ok := err.(*CorruptError)
66		if !ok {
67			t.Fatalf("应为 *CorruptError，得到 %T: %v", err, err)
68		}
69		if ce.Record != id {
70			t.Fatalf("CorruptError 应保留被拒绝的记录标识 %s，得到 %q", id, ce.Record)
71		}
72		if !strings.Contains(ce.Error(), "格式") || !strings.Contains(ce.Error(), fmt.Sprintf("%d", format)) {
73			t.Fatalf("错误应指出不支持的格式编号 %d: %v", format, ce)
74		}
75		if errors.As(err, new(*VersionRejectedError)) {
76			t.Fatalf("格式问题不应报成版本拒绝: %v", err)
77		}
78	}
79	
80	// TestLatestAndRecordUnsupportedFormatCorrupt 校验和匹配、世界状态合法、
81	// 规则版本也在可接受集合内，但格式编号不是 1 的记录仍属损坏：Latest 与
82	// Record 都返回保留记录标识并指出格式编号的 *CorruptError，不按版本拒绝
83	// 处理；读取保持只读，不修补这份记录。
84	func TestLatestAndRecordUnsupportedFormatCorrupt(t *testing.T) {
85		for _, format := range []int{2, 0, -1, 7} {
86			t.Run(fmt.Sprintf("format=%d", format), func(t *testing.T) {
87				a, _ := newTestArchive(t)
88				ids := saveN(t, a, "s", 1) // r1 r0
89				rewriteRecordFormat(t, a, ids[0], format)
90				before := recordFileBytes(t, a, ids[0])
91	
92				_, err := a.Latest("s", []string{"v1"})
93				assertUnsupportedFormatCorrupt(t, err, ids[0], format)
94	
95				_, err = a.Record("s", ids[0], []string{"v1"})
96				assertUnsupportedFormatCorrupt(t, err, ids[0], format)
97	
98				// 记录没有被悄悄修补或删除，槽指向不变。
99				if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
100					t.Fatal("读取改写了未知格式记录")
101				}
102				if p, err := a.readSlotPointerLocked("s"); err != nil || p.Latest != ids[0] {
103					t.Fatalf("槽指向不应改变: %+v err=%v", p, err)
104				}
105	
106				// 本槽格式 1 的完好记录不受影响，仍可正常读取。
107				if _, err := a.Record("s", ids[1], []string{"v1"}); err != nil {
108					t.Fatalf("格式 1 的历史记录应可读: %v", err)
109				}
110			})
111		}
112	}
113	
114	// TestMissingFormatFieldRejected 记录文件缺少 format 字段时按零值处理，
115	// 即使校验和（按零值重算）匹配、世界状态合法也拒绝读取。
116	func TestMissingFormatFieldRejected(t *testing.T) {
117		a, _ := newTestArchive(t)
118		info := saveBase(t, a, "s")
119		dropRecordFormatField(t, a, info.ID)
120	
121		_, err := a.Latest("s", []string{"v1"})
122		assertUnsupportedFormatCorrupt(t, err, info.ID, 0)
123	}
124	
125	// TestFormatCheckIndependentOfVersion 格式编号与规则版本分别判断：格式 1
126	// 的完好记录仍按版本集合决定能否读取；格式不受支持的记录即使版本不被
127	// 接受也报损坏而非版本拒绝，且读取不改写记录中的规则。
128	func TestFormatCheckIndependentOfVersion(t *testing.T) {
129		a, _ := newTestArchive(t)
130		ids := saveN(t, a, "s", 1)
131	
132		// 格式 1 完好记录：版本不在集合内仍是版本拒绝。
133		if _, err := a.Latest("s", []string{"other"}); !errors.As(err, new(*VersionRejectedError)) {
134			t.Fatalf("格式 1 完好记录应仍按版本集合判断，得到 %T: %v", err, err)
135		}
136	
137		// 格式不受支持且版本也不被接受：报损坏，不报版本拒绝。
138		rewriteRecordFormat(t, a, ids[0], 2)
139		_, err := a.Latest("s", []string{"other"})
140		assertUnsupportedFormatCorrupt(t, err, ids[0], 2)
141	
142		// 记录中的规则保持原样，未被读取改写。
143		env, err := loadRecord(recordPath(a.dir, ids[0]))
144		if err != nil {
145			t.Fatal(err)
146		}
147		if env.State.Rules.Version != "v1" || env.Format != 2 {
148			t.Fatalf("读取不应改写记录: format=%d version=%s", env.Format, env.State.Rules.Version)
149		}
150	}
151	
152	// TestRecoverSkipsUnsupportedFormat 恢复读取与恢复预览按本槽保存次序越过
153	// 格式不受支持的记录；连续多份未知格式记录也不会遮住其后格式 1 的完好
154	// 记录。预览的当前标识仍是槽实际指向的记录，来源是选中的完好记录；恢复
155	// 不修补格式、不删除文件、不改变槽指向。
156	func TestRecoverSkipsUnsupportedFormat(t *testing.T) {
157		a, _ := newTestArchive(t)
158		ids := saveN(t, a, "s", 2) // r2(time 2) r1(time 1) r0(time 0)
159		rewriteRecordFormat(t, a, ids[0], 2)
160		rewriteRecordFormat(t, a, ids[1], 3)
161	
162		rec, err := a.RecoverLatest("s", []string{"v1"})
163		if err != nil {
164			t.Fatalf("应越过未知格式记录恢复: %v", err)
165		}
166		if rec.ID != ids[2] || rec.State.Time != 0 {
167			t.Fatalf("应恢复 %s（时间片 0），得到 %s（时间片 %d）", ids[2], rec.ID, rec.State.Time)
168		}
169	
170		pv, err := a.PreviewRecovery("s", []string{"v1"})
171		if err != nil {
172			t.Fatalf("预览应越过未知格式记录: %v", err)
173		}
174		if pv.Current != ids[0] {
175			t.Fatalf("预览当前标识应是槽实际指向的 %s，得到 %s", ids[0], pv.Current)
176		}
177		if pv.Source != ids[2] {
178			t.Fatalf("预览来源应是 %s，得到 %s", ids[2], pv.Source)
179		}
180	
181		// 未知格式记录没有被修补或删除，槽指向不变，重复恢复结果一致。
182		if p, err := a.readSlotPointerLocked("s"); err != nil || p.Latest != ids[0] {
183			t.Fatalf("恢复不应改变槽指向: %+v err=%v", p, err)
184		}
185		if _, err := a.Latest("s", []string{"v1"}); err == nil {
186			t.Fatal("恢复/预览不应修补未知格式记录")
187		}
188		rec2, err := a.RecoverLatest("s", []string{"v1"})
189		if err != nil || rec2.ID != ids[2] {
190			t.Fatalf("重复恢复结果应一致: %+v err=%v", rec2, err)
191		}
192	}
193	
194	// TestRecoverAllUnsupportedFormatUnrecoverable 本槽没有任何格式受支持的
195	// 完好记录时，恢复读取与恢复预览都返回可由 errors.Is 判断的
196	// ErrUnrecoverable；分支槽只用自己的历史，不跨入来源槽。
197	func TestRecoverAllUnsupportedFormatUnrecoverable(t *testing.T) {
198		a, _ := newTestArchive(t)
199		src := saveBase(t, a, "src")
200		if _, err := a.Branch("src", src.ID, "b"); err != nil {
201			t.Fatal(err)
202		}
203		p, err := a.readSlotPointerLocked("b")
204		if err != nil {
205			t.Fatal(err)
206		}
207		rewriteRecordFormat(t, a, p.Latest, 2)
208	
209		// 分支唯一记录格式不受支持：不可恢复，且不会回退到来源槽的完好记录。
210		if _, err := a.RecoverLatest("b", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
211			t.Fatalf("分支不应跨入来源槽，得到 %T: %v", err, err)
212		}
213		if _, err := a.PreviewRecovery("b", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
214			t.Fatalf("预览同样应不可恢复，得到 %T: %v", err, err)
215		}
216	
217		// 来源槽自己的完好记录不受影响。
218		if _, err := a.RecoverLatest("src", []string{"v1"}); err != nil {
219			t.Fatalf("来源槽应可正常恢复: %v", err)
220		}
221	}
222	
223	// TestUnsupportedFormatLegacyPointerHistory 旧格式裸指针沿父链重建历史时，
224	// 未知格式记录同样校验不过：重建停在那里，不依靠未知格式记录中的父标识
225	// 继续查找，无法确认归属的更老记录不进入恢复候选。
226	func TestUnsupportedFormatLegacyPointerHistory(t *testing.T) {
227		a, dir := newTestArchive(t)
228		ids := saveN(t, a, "s", 3) // r3 r2 r1 r0
229		rewriteRecordFormat(t, a, ids[2], 2)
230		writeLegacyPointer(t, a, "s", ids[0])
231	
232		a2, err := Open(dir)
233		if err != nil {
234			t.Fatal(err)
235		}
236		// 最新与次新完好：恢复仍命中最新记录。
237		rec, err := a2.RecoverLatest("s", []string{"v1"})
238		if err != nil {
239			t.Fatalf("未知格式记录之前的完好记录应可恢复: %v", err)
240		}
241		if rec.ID != ids[0] {
242			t.Fatalf("应恢复最新记录 %s，得到 %s", ids[0], rec.ID)
243		}
244	
245		// 最新与次新也损坏后，链在未知格式记录处断裂，首存记录无法确认归属。
246		corruptChecksum(t, dir, ids[0])
247		corruptChecksum(t, dir, ids[1])
248		if _, err := a2.RecoverLatest("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
249			t.Fatalf("断裂处更老的记录不应进入候选，得到 %T: %v", err, err)
250		}
251	}
252	
253	// TestSaveSourcesUnsupportedFormatRejected 把未知格式记录用作保存来源时
254	// 一律按损坏拒绝：分支、覆盖、升级、迁移与确认恢复都不产生新记录，不改变
255	// 槽指向或已有历史，也不把未知格式内容重新保存成格式 1。
256	func TestSaveSourcesUnsupportedFormatRejected(t *testing.T) {
257		a, _ := newTestArchive(t)
258		ids := saveN(t, a, "s", 2) // r2 r1 r0
259		rewriteRecordFormat(t, a, ids[0], 2)
260		before := recordCount(t, a)
261	
262		// 分支：来源未知格式。
263		_, err := a.Branch("s", ids[0], "b")
264		assertUnsupportedFormatCorrupt(t, err, ids[0], 2)
265		if _, err := a.readLatestLocked("b"); !errors.As(err, new(*NotFoundError)) {
266			t.Fatalf("不应创建目标槽，得到 %v", err)
267		}
268	
269		// 覆盖：当前记录未知格式。
270		rec, err := a.Record("s", ids[1], []string{"v1"})
271		if err != nil {
272			t.Fatal(err)
273		}
274		w, err := WorldFromState(rec.State)
275		if err != nil {
276			t.Fatal(err)
277		}
278		if _, err := w.Apply(Commit{Time: 9}); err != nil {
279			t.Fatal(err)
280		}
281		_, err = a.Replace("s", w, ids[0])
282		assertUnsupportedFormatCorrupt(t, err, ids[0], 2)
283	
284		// 升级：检查与正式升级都拒绝。
285		_, err = a.CheckUpgrade("s", []string{"v1"}, v2Rules())
286		assertUnsupportedFormatCorrupt(t, err, ids[0], 2)
287		_, err = a.Upgrade("s", []string{"v1"}, v2Rules(), ids[0])
288		assertUnsupportedFormatCorrupt(t, err, ids[0], 2)
289	
290		// 迁移：预览与正式迁移都拒绝。
291		_, err = a.PreviewMigration("s", []string{"v1"}, v2Rules(), nil, nil)
292		assertUnsupportedFormatCorrupt(t, err, ids[0], 2)
293		_, err = a.Migrate("s", []string{"v1"}, v2Rules(), nil, nil, ids[0])
294		assertUnsupportedFormatCorrupt(t, err, ids[0], 2)
295	
296		// 确认恢复：来源未知格式。
297		_, err = a.ConfirmRecovery("s", ids[0], ids[0], []string{"v1"})
298		assertUnsupportedFormatCorrupt(t, err, ids[0], 2)
299	
300		// 全部拒绝：不产生新记录，槽指向与历史保持原样。
301		if got := recordCount(t, a); got != before {
302			t.Fatalf("被拒绝的保存不应产生新记录: %d -> %d", before, got)
303		}
304		p, err := a.readSlotPointerLocked("s")
305		if err != nil {
306			t.Fatal(err)
307		}
308		if p.Latest != ids[0] {
309			t.Fatalf("槽指向不应改变: %s -> %s", ids[0], p.Latest)
310		}
311		if len(p.History) != 3 {
312			t.Fatalf("历史不应改变: %v", p.History)
313		}
314	
315		// 本槽格式 1 的完好记录仍可正常作为分支来源。
316		if _, err := a.Branch("s", ids[1], "ok"); err != nil {
317			t.Fatalf("格式 1 的来源应可分支: %v", err)
318		}
319	}
320	
321	// TestConfirmRecoveryFromFormat1WhenCurrentUnsupported 只有当前记录格式
322	// 不受支持时，仍可按已有恢复流程从本槽另一份格式 1 的完好记录确认恢复：
323	// 预览选中完好的旧记录，确认后产生格式 1 的新记录并指向它。
324	func TestConfirmRecoveryFromFormat1WhenCurrentUnsupported(t *testing.T) {
325		a, _ := newTestArchive(t)
326		ids := saveN(t, a, "s", 1) // r1(time 1) r0(time 0)
327		rewriteRecordFormat(t, a, ids[0], 2)
328	
329		pv, err := a.PreviewRecovery("s", []string{"v1"})
330		if err != nil {
331			t.Fatalf("预览应选中格式 1 的旧记录: %v", err)
332		}
333		if pv.Current != ids[0] || pv.Source != ids[1] {
334			t.Fatalf("预览应为 current=%s source=%s，得到 current=%s source=%s",
335				ids[0], ids[1], pv.Current, pv.Source)
336		}
337	
338		info, err := a.ConfirmRecovery("s", pv.Current, pv.Source, []string{"v1"})
339		if err != nil {
340			t.Fatalf("从格式 1 的完好记录确认恢复应成功: %v", err)
341		}
342		if info.Parent != ids[1] {
343			t.Fatalf("新记录应以来源为父: %s", info.Parent)
344		}
345	
346		// 新记录是格式 1 的完好记录，槽指向它，旧历史原样保留。
347		env, err := loadRecord(recordPath(a.dir, info.ID))
348		if err != nil {
349			t.Fatal(err)
350		}
351		if env.Format != recordFormatVersion {
352			t.Fatalf("确认恢复产生的新记录应为格式 1，得到 %d", env.Format)
353		}
354		rec, err := a.Latest("s", []string{"v1"})
355		if err != nil || rec.ID != info.ID || rec.State.Time != 0 {
356			t.Fatalf("恢复后最新记录应可读且内容来自来源: %+v err=%v", rec, err)
357		}
358		if _, err := a.Record("s", ids[1], []string{"v1"}); err != nil {
359			t.Fatalf("来源记录应仍可读取: %v", err)
360		}
361	}
